// expect: exit 0
// screen: 0 1.000000000 is not 1
// screen: 1 -40.0 32.0 98.6 212.0
int main(void)
{
    float s = 0;
    int i;
    cls();
    for (i = 0; i < 10; i++)
        s += 0.1;
    if (s != 1)
        printf("%.9f is not 1\n", s);
    for (i = -40; i <= 100; i += i < 37 ? (i < 0 ? 40 : 37) : 63)
        printf("%.1f ", i * 1.8 + 32);
    return s - 1 > 1e-8;
}
